package com.example.demo.model;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * One-time invite token generated by a user to refer a friend.
 * Stored as a BCrypt hash; the plain token is only in the email/link.
 */
@Entity
@Table(name = "invite_tokens")
public class InviteToken {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** BCrypt hash of the raw token string. */
    @Column(nullable = false, unique = true)
    private String tokenHash;

    /** The user who created this invite. */
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "inviter_id", nullable = false,
                foreignKey = @ForeignKey(name = "fk_invite_inviter"))
    private User inviter;

    @Column(nullable = false)
    private LocalDateTime expiry;

    @Column(name = "created_at", nullable = false, updatable = false)
    private LocalDateTime createdAt;

    /** Set true once the token has been used to register someone. */
    @Column(nullable = false)
    private boolean used = false;

    public InviteToken() {}

    @PrePersist
    protected void onCreate() {
        this.createdAt = LocalDateTime.now();
    }

    public Long getId() { return id; }

    public String getTokenHash() { return tokenHash; }
    public void setTokenHash(String tokenHash) { this.tokenHash = tokenHash; }

    public User getInviter() { return inviter; }
    public void setInviter(User inviter) { this.inviter = inviter; }

    public LocalDateTime getExpiry() { return expiry; }
    public void setExpiry(LocalDateTime expiry) { this.expiry = expiry; }

    public LocalDateTime getCreatedAt() { return createdAt; }

    public boolean isUsed() { return used; }
    public void setUsed(boolean used) { this.used = used; }
}
